    /// <summary>
    /// Informs TDLib that the user viewed a video message advertisement
    /// </summary>
    public Task<TdLib.TdApi.Objects.Ok> ViewVideoMessageAdvertisementAsync(long advertisementUniqueId = default)
    {

           using var activity =  StartCallActivity("ViewVideoMessageAdvertisementAsync", typeof(ViewVideoMessageAdvertisement).FullName ?? "ViewVideoMessageAdvertisementAsync");

           try
           {
             return client.ViewVideoMessageAdvertisementAsync(advertisementUniqueId);
           }
           catch (Exception ex)
           {
               MarkAsError(activity, ex);
               throw;
           }
    }
